DO $$ BEGIN
  CREATE TYPE day_of_week_enum AS ENUM (
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
    'Sunday'
  );
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE time_of_day_enum AS ENUM ('Morning', 'Afternoon', 'Evening', 'Night');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE TABLE
  IF NOT EXISTS "dim_location" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" text NOT NULL
  );

CREATE TABLE
  IF NOT EXISTS "dim_charger" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "location_id" bigint NOT NULL,
    "type" text NOT NULL
  );

CREATE TABLE
  IF NOT EXISTS "dim_user" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "car_model" text NOT NULL,
    "membership_type" text NOT NULL
  );

CREATE TABLE
  IF NOT EXISTS "dim_date" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "iso" varchar NOT NULL,
    "day" integer NOT NULL,
    "month" integer NOT NULL,
    "year" integer NOT NULL,
    "day_of_week" day_of_week_enum NOT NULL,
    "week" integer NOT NULL
  );

CREATE TABLE
  IF NOT EXISTS "dim_time" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "date_id" bigint NOT NULL,
    "time_of_day" time_of_day_enum NOT NULL,
    "hours" integer NOT NULL,
    "minutes" integer NOT NULL
  );

CREATE TABLE
  IF NOT EXISTS "facts_charges" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "charger_id" bigint NOT NULL,
    "user_id" bigint NOT NULL,
    "start_time" bigint NOT NULL,
    "end_time" bigint NOT NULL,
    "duration_hours" float NOT NULL,
    "energy_consumed_kwh" float,
    "charging_rate_kwh" float,
    "charging_cost_kwh" float NOT NULL,
    "battery_percentage_start" float NOT NULL,
    "battery_percentage_end" float NOT NULL,
    "vehicle_age_years" float NOT NULL,
    "distance_since_last_charge_km" float,
    "ambient_temperature_celsius" float NOT NULL
  );

DO $$ BEGIN
  ALTER TABLE "dim_charger"
   ADD CONSTRAINT fk_charger_location
   FOREIGN KEY ("location_id")
   REFERENCES "dim_location" ("id")
   DEFERRABLE INITIALLY DEFERRED;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE "dim_time"
   ADD CONSTRAINT fk_time_date
   FOREIGN KEY ("date_id")
   REFERENCES "dim_date" ("id")
   DEFERRABLE INITIALLY DEFERRED;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE "facts_charges"
   ADD CONSTRAINT fk_facts_charger
   FOREIGN KEY ("charger_id")
   REFERENCES "dim_charger" ("id")
   DEFERRABLE INITIALLY DEFERRED;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE "facts_charges"
   ADD CONSTRAINT fk_facts_user
   FOREIGN KEY ("user_id")
   REFERENCES "dim_user" ("id")
   DEFERRABLE INITIALLY DEFERRED;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE "facts_charges"
   ADD CONSTRAINT fk_facts_start_time
   FOREIGN KEY ("start_time")
   REFERENCES "dim_time" ("id")
   DEFERRABLE INITIALLY DEFERRED;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  ALTER TABLE "facts_charges"
   ADD CONSTRAINT fk_facts_end_time
   FOREIGN KEY ("end_time")
   REFERENCES "dim_time" ("id")
   DEFERRABLE INITIALLY DEFERRED;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;
